INSERT INTO dish_ingredients (dish_id, ingredient_id, quantity, unit, order_index, show_in_animation, created_at, updated_at)
SELECT d.id, i.id, 160.000, 'ml', 4, 1, NOW(), NOW()
FROM dishes d
JOIN ingredients i ON i.restaurant_id = d.restaurant_id AND i.name = 'sparkling water'
WHERE d.restaurant_id = 29 AND d.name = 'Yuzu Green Tea Cooler';

